const candidate = $json?.candidates?.[0]?.content?.parts?.[0]?.text;
if (!candidate) throw new Error('Gemini returned no usable content');
const cleaned = String(candidate).replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```$/,'').trim();
let result;
try { result = JSON.parse(cleaned); } catch { throw new Error(`Gemini returned invalid JSON: ${cleaned}`); }
const required = ['summary','skillScore','recommendedRoles','strongSkills','missingSkills','technicalQuestions','hrQuestions','finalRecommendation'];
for (const key of required) if (!(key in result)) throw new Error(`Missing AI field: ${key}`);
result.skillScore = Math.max(0, Math.min(100, Number(result.skillScore) || 0));
return [{ json: result }];
